/* Power Shift — Corporate / executive theme: deep navy, slate, brass-gold + teal. Boardroom, not factory. */
.powershift-container {
    padding: 28px;
    background: #0d1320;
    background-image: radial-gradient(1200px 500px at 80% -10%, rgba(201,162,77,0.08) 0%, transparent 60%), linear-gradient(180deg, #0f1626 0%, #0b1019 100%);
    min-height: 100vh;
    font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
    color: #e8ecf3;
}
.powershift-header {
    background: linear-gradient(135deg, #14203a 0%, #1b2c4e 100%);
    color: #f4f7fc;
    padding: 32px 36px;
    border-radius: 8px;
    margin-bottom: 24px;
    border-left: 6px solid #c9a24d;
    box-shadow: 0 10px 30px rgba(0,0,0,0.5);
    position: relative;
    overflow: hidden;
}
.powershift-header::after {
    content: "";
    position: absolute;
    inset: 0;
    background: repeating-linear-gradient(135deg, rgba(201,162,77,0.04) 0 14px, transparent 14px 28px);
    pointer-events: none;
}
.powershift-header-tag {
    display: inline-block;
    background: rgba(201,162,77,0.16);
    color: #e2c07f;
    padding: 4px 12px;
    border-radius: 4px;
    font-size: 0.73rem;
    letter-spacing: 0.1em;
    text-transform: uppercase;
    margin-bottom: 12px;
    font-weight: 700;
    position: relative;
}
.powershift-header h1 {
    font-size: 2.1rem;
    font-weight: 800;
    margin: 0 0 10px 0;
    letter-spacing: -0.01em;
    position: relative;
}
.powershift-subtitle {
    margin: 0;
    font-size: 1.02rem;
    color: #b7c2d6;
    max-width: 780px;
    line-height: 1.55;
    position: relative;
}
.powershift-period-counter {
    background: #131c2e;
    border: 1px solid #29354c;
    border-radius: 8px;
    padding: 14px 22px;
    margin-bottom: 24px;
    font-size: 0.95rem;
    color: #93a0b8;
    font-weight: 500;
    display: flex;
    align-items: center;
    gap: 8px;
    flex-wrap: wrap;
}
.powershift-period-counter span {
    font-weight: 700;
    color: #e8ecf3;
}
.powershift-round-name {
    margin-left: 14px;
    color: #c9a24d;
    text-transform: uppercase;
    letter-spacing: 0.06em;
    font-size: 0.85rem;
}
.powershift-clock {
    margin-left: auto;
    color: #6fd3c0 !important;
    font-variant-numeric: tabular-nums;
    background: rgba(111,211,192,0.12);
    padding: 4px 12px;
    border-radius: 4px;
    font-size: 0.85rem;
}
.powershift-status-cards {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(210px, 1fr));
    gap: 16px;
    margin-bottom: 24px;
}
.powershift-status-card {
    background: #131c2e;
    border: 1px solid #29354c;
    border-radius: 8px;
    padding: 22px 20px;
    transition: transform 0.2s ease, box-shadow 0.2s ease;
}
.powershift-status-card:hover {
    transform: translateY(-2px);
    box-shadow: 0 8px 22px rgba(0,0,0,0.45);
}
.powershift-card-primary {
    border-top: 4px solid #c9a24d;
    background: linear-gradient(180deg, #1d2336 0%, #131c2e 100%);
}
.powershift-card-risk {
    border-top: 4px solid #d9544d;
    background: linear-gradient(180deg, #2a1a1e 0%, #131c2e 100%);
}
.powershift-label {
    color: #8593ab;
    font-size: 0.72rem;
    text-transform: uppercase;
    letter-spacing: 0.1em;
    font-weight: 700;
    margin-bottom: 10px;
}
.powershift-value {
    font-size: 2.5rem;
    font-weight: 800;
    color: #f4f7fc;
    line-height: 1;
    margin-bottom: 6px;
    font-variant-numeric: tabular-nums;
}
.powershift-card-primary .powershift-value {
    color: #e2c07f;
}
.powershift-card-risk .powershift-value {
    color: #f08079;
}
.powershift-sublabel {
    color: #76849c;
    font-size: 0.78rem;
}
.powershift-briefing {
    background: #14203a;
    border: 1px solid #2d3c5c;
    border-left: 5px solid #c9a24d;
    border-radius: 8px;
    padding: 22px 24px;
    margin-bottom: 24px;
    display: flex;
    gap: 18px;
    align-items: flex-start;
}
.powershift-briefing-icon {
    font-size: 2rem;
    line-height: 1;
    flex-shrink: 0;
}
.powershift-briefing-body {
    flex: 1;
}
.powershift-briefing-title {
    font-size: 1.08rem;
    font-weight: 800;
    color: #e2c07f;
    margin-bottom: 8px;
}
.powershift-briefing-text {
    color: #cbd4e3;
    line-height: 1.6;
    font-size: 0.95rem;
}
.powershift-briefing-text strong {
    color: #e2c07f;
}
.powershift-controls {
    background: #131c2e;
    border: 1px solid #29354c;
    border-radius: 8px;
    padding: 26px;
    margin-bottom: 24px;
}
.powershift-controls h3 {
    font-size: 1.1rem;
    font-weight: 800;
    color: #f4f7fc;
    margin: 0 0 18px 0;
    padding-bottom: 12px;
    border-bottom: 1px solid #29354c;
}
.powershift-panel {
    margin-bottom: 8px;
}
.powershift-controls label {
    display: block;
    font-size: 0.85rem;
    font-weight: 600;
    color: #c3ccdc;
    margin-bottom: 6px;
    margin-top: 16px;
}
.powershift-controls input[type="number"],
.powershift-controls input[type="text"],
.powershift-controls select {
    width: 100%;
    background-color: #0b121f;
    border: 1px solid #33415c;
    color: #e8ecf3;
    border-radius: 5px;
    padding: 10px 12px;
    font-size: 0.95rem;
    font-family: inherit;
    transition: border-color 0.2s ease, box-shadow 0.2s ease;
}
.powershift-controls select option {
    background-color: #0b121f;
    color: #e8ecf3;
}
.powershift-controls input[type="number"]:focus,
.powershift-controls input[type="text"]:focus,
.powershift-controls select:focus {
    outline: none;
    border-color: #c9a24d;
    box-shadow: 0 0 0 3px rgba(201,162,77,0.18);
}
.powershift-controls input[type="range"] {
    width: 100%;
    accent-color: #c9a24d;
    margin-top: 8px;
}
.powershift-range-readout {
    font-size: 0.85rem;
    color: #93a0b8;
    margin-top: 6px;
}
.powershift-range-readout span:last-child {
    color: #e2c07f;
    font-weight: 700;
}
.powershift-controls .btn {
    margin-top: 24px;
    padding: 12px 24px;
    border-radius: 5px;
    font-weight: 700;
    font-size: 0.95rem;
    letter-spacing: 0.02em;
    border: none;
    transition: background 0.2s ease, transform 0.15s ease;
}
.powershift-controls .btn-primary {
    background: #c9a24d;
    color: #1a1304;
}
.powershift-controls .btn-primary:hover {
    background: #ddb964;
    transform: translateY(-1px);
}
.powershift-controls .btn-outline-secondary {
    background: transparent;
    color: #93a0b8;
    border: 1px solid #33415c;
    margin-left: 10px;
}
.powershift-controls .btn-outline-secondary:hover {
    background: #1c2638;
    color: #e8ecf3;
}
.powershift-coach {
    background: linear-gradient(135deg, #14203a 0%, #1d2c49 100%);
    color: #e8ecf3;
    border-radius: 8px;
    padding: 22px 26px;
    margin-bottom: 24px;
    border-left: 5px solid #6fd3c0;
}
.powershift-coach-header {
    font-size: 0.78rem;
    text-transform: uppercase;
    letter-spacing: 0.14em;
    color: #6fd3c0;
    font-weight: 800;
    margin-bottom: 10px;
}
.powershift-coach-body {
    line-height: 1.6;
    font-size: 0.98rem;
    color: #e8ecf3;
}
.powershift-coach-body strong {
    color: #e2c07f;
}
.powershift-history {
    background: #131c2e;
    border: 1px solid #29354c;
    border-radius: 8px;
    padding: 24px;
    margin-bottom: 24px;
    overflow-x: auto;
}
.powershift-history h3 {
    font-size: 1.05rem;
    font-weight: 800;
    color: #f4f7fc;
    margin: 0 0 14px 0;
}
.powershift-history table {
    margin-bottom: 0;
    color: #e8ecf3;
    width: 100%;
}
.powershift-history table th {
    background: #0f1626;
    color: #93a0b8;
    font-size: 0.76rem;
    text-transform: uppercase;
    letter-spacing: 0.06em;
    font-weight: 700;
    border-bottom: 2px solid #29354c;
    padding: 10px 12px;
}
.powershift-history table td {
    color: #d3dae6;
    font-size: 0.9rem;
    padding: 10px 12px;
    border-bottom: 1px solid #1c2638;
}
.powershift-chart {
    background: #131c2e;
    border: 1px solid #29354c;
    border-radius: 8px;
    padding: 24px;
    margin-bottom: 24px;
    height: 380px;
}
.powershift-chart h3 {
    font-size: 1.05rem;
    font-weight: 800;
    color: #f4f7fc;
    margin: 0 0 14px 0;
}
.powershift-chart canvas {
    max-height: 300px;
}
@media (max-width: 768px) {
    .powershift-container { padding: 16px; }
    .powershift-header { padding: 24px 22px; }
    .powershift-header h1 { font-size: 1.5rem; }
    .powershift-status-cards { grid-template-columns: repeat(2, 1fr); }
    .powershift-value { font-size: 1.9rem; }
    .powershift-period-counter { flex-wrap: wrap; }
    .powershift-clock { margin-left: 0; width: 100%; margin-top: 6px; text-align: center; }
    .powershift-round-name { margin-left: 0; }
}


/* FIX v1.1.0 — completion / leadership-debrief screen */
.ps-completion { padding: 10px 6px; text-align: center; }
.ps-completion-heading { font-size: 12px; letter-spacing: .08em; text-transform: uppercase; color: #64748b; margin-bottom: 6px; }
.ps-completion-verdict { font-size: 20px; font-weight: 700; color: #0f172a; margin-bottom: 8px; }
.ps-completion-score { font-size: 16px; color: #0f172a; margin-bottom: 14px; }
.ps-completion-score strong { color: #9333ea; }
.ps-completion-metrics { display: flex; flex-wrap: wrap; justify-content: center; gap: 10px; margin-bottom: 16px; }
.ps-completion-metric { display: inline-flex; flex-direction: column; align-items: center; gap: 2px; padding: 8px 12px; background: #f1f5f9; border-radius: 8px; min-width: 100px; }
.ps-completion-metric span { font-size: 11px; letter-spacing: .03em; text-transform: uppercase; color: #64748b; }
.ps-completion-metric strong { font-size: 16px; color: #0f172a; }
.ps-completion-insights { list-style: none; padding: 0; margin: 0 auto; max-width: 680px; text-align: left; }
.ps-completion-insights li { padding: 9px 13px; margin-bottom: 7px; background: #faf5ff; border-left: 3px solid #9333ea; border-radius: 4px; color: #1e293b; font-size: 13px; }

