(function() {
    'use strict';

    class PowerShiftAdapter extends USF.SimulationAdapter {
        constructor() {
            super();
            this.name = `Power Shift`;
            this.version = `1.1.0`;

            this.ROUNDS = [
                { id: 1, titleKey: `briefing_title_r1`, textKey: `briefing_text_r1`, panelId: `round1Panel`, nameKey: `round_name_r1`, clockKey: `clock_r1` },
                { id: 2, titleKey: `briefing_title_r2`, textKey: `briefing_text_r2`, panelId: `round2Panel`, nameKey: `round_name_r2`, clockKey: `clock_r2` },
                { id: 3, titleKey: `briefing_title_r3`, textKey: `briefing_text_r3`, panelId: `round3Panel`, nameKey: `round_name_r3`, clockKey: `clock_r3` },
                { id: 4, titleKey: `briefing_title_r4`, textKey: `briefing_text_r4`, panelId: `round4Panel`, nameKey: `round_name_r4`, clockKey: `clock_r4` }
            ];

            // The concept's truth.
            this.CALIBRATED_EV = 5.1;   // €M base-case expected value of the Q3 pipeline
            this.REALIZED_Q3 = 4.8;     // €M realized at debrief (decision tree: "if Q3 lands at €4.8M")
            this.BAND_LOW = 4.4;
            this.BAND_HIGH = 5.9;
        }

        initialize(state) {
            if (!state.domainState || Object.keys(state.domainState).length === 0) {
                state.domainState = {
                    trust: 62,            // starting trust index across 38 reports
                    accountRisk: 30,      // baseline risk to the €9.5M Núria portfolio
                    influence: 60,        // authority partners actually back
                    overconfGap: 0,       // €M committed - calibrated EV
                    committedForecast: 0, // €M, set in round 3
                    nuriaSecured: false,  // did the highest-leverage relationship get prioritised early
                    nuriaRetained: false, // round 4 outcome
                    forecastMissed: false,
                    hrComplaints: 5,      // private complaints to HR (escalation signal)
                    trustHistory: [62],
                    riskHistory: [30],
                    coachMessages: [],
                    lastCoach: ``
                };
            }
            if (!state.decisions || Object.keys(state.decisions).length === 0) {
                state.decisions = {
                    swing: `nuria`,
                    trap: `unilateral`,
                    awareness: 65,
                    staffing: `advisory`,
                    sequence: `private`,
                    credit: `nuria`,
                    forecast: 5.1,
                    band: `band`,
                    consult: `consult`,
                    offer: `redefine`,
                    share: `cochair`,
                    boundary: `forecast`,
                    recover: 70
                };
            }
            this._updateBriefing(state);
        }

        validateDecisions(decisions) {
            const state = window.mySimulation.state;
            const round = state.currentPeriod || 1;
            const warn = (k) => window.mySimulation.uiManager.showNotification(window.mySimulation.t(k), `warning`);

            if (round === 1) {
                const sw = document.getElementById(`swingInput`);
                const tr = document.getElementById(`trapInput`);
                const aw = document.getElementById(`awarenessInput`);
                if (sw) decisions.swing = sw.value;
                if (tr) decisions.trap = tr.value;
                if (aw) decisions.awareness = parseInt(aw.value, 10);
                if (!Number.isFinite(decisions.awareness) || decisions.awareness < 0 || decisions.awareness > 100) {
                    warn(`warn_awareness_range`); return false;
                }
            } else if (round === 2) {
                const st = document.getElementById(`staffingInput`);
                const se = document.getElementById(`sequenceInput`);
                const cr = document.getElementById(`creditInput`);
                if (st) decisions.staffing = st.value;
                if (se) decisions.sequence = se.value;
                if (cr) decisions.credit = cr.value;
            } else if (round === 3) {
                const fc = document.getElementById(`forecastInput`);
                const bd = document.getElementById(`bandInput`);
                const co = document.getElementById(`consultInput`);
                if (fc) decisions.forecast = parseFloat(fc.value);
                if (bd) decisions.band = bd.value;
                if (co) decisions.consult = co.value;
                if (!Number.isFinite(decisions.forecast) || decisions.forecast < 3.5 || decisions.forecast > 6.5) {
                    warn(`warn_forecast_range`); return false;
                }
            } else if (round === 4) {
                const of = document.getElementById(`offerInput`);
                const sh = document.getElementById(`shareInput`);
                const bo = document.getElementById(`boundaryInput`);
                const rc = document.getElementById(`recoverInput`);
                if (of) decisions.offer = of.value;
                if (sh) decisions.share = sh.value;
                if (bo) decisions.boundary = bo.value;
                if (rc) decisions.recover = parseInt(rc.value, 10);
                if (!Number.isFinite(decisions.recover) || decisions.recover < 0 || decisions.recover > 100) {
                    warn(`warn_recover_range`); return false;
                }
            }
            return true;
        }

        calculateResults(state) {
            const d = state.decisions;
            const ds = state.domainState;
            const round = state.currentPeriod;

            let trustDelta = 0, riskDelta = 0, influenceDelta = 0;
            let coachKey = `coach_default`;
            let summaryKey = `sum_default`;

            if (round === 1) {
                // Diagnose the transition. Naming the unilateral trap + a high honest self-check
                // is the self-awareness that lets you counter overconfidence later.
                if (d.swing === `nuria`) {
                    // The highest-leverage relationship IS the demoted peer (Decision Tree #6).
                    riskDelta -= 8; trustDelta += 4; ds.nuriaSecured = true; coachKey = `coach_r1_nuria`;
                } else if (d.swing === `star`) {
                    riskDelta += 2; coachKey = `coach_r1_star`;
                } else if (d.swing === `partners`) {
                    // Chasing the people who promoted you = the overconfidence pull.
                    riskDelta += 6; trustDelta -= 4; coachKey = `coach_r1_partners`;
                } else if (d.swing === `backers`) {
                    riskDelta += 4; trustDelta -= 2; coachKey = `coach_r1_backers`;
                }

                if (d.trap === `unilateral`) {
                    // Correctly naming the real trap = self-awareness that pays off all game.
                    influenceDelta += 6; trustDelta += 3;
                    ds.namedTrap = true;
                } else {
                    influenceDelta -= 2; ds.namedTrap = false;
                    coachKey = (d.swing === `nuria`) ? `coach_r1_trapwrong` : coachKey;
                }

                // Honest high self-check (>=60) = naming the urge so you can regulate it.
                if (d.awareness >= 60) {
                    trustDelta += 4;
                    coachKey = (d.swing === `nuria` && d.trap === `unilateral`) ? `coach_r1_aware` : coachKey;
                } else if (d.awareness <= 25) {
                    // Denying the urge to assert is exactly how the newly powerful get blindsided.
                    trustDelta -= 4; influenceDelta -= 3;
                }
                summaryKey = (d.swing === `nuria` && d.trap === `unilateral`) ? `sum_r1_good` : `sum_r1_weak`;
            } else if (round === 2) {
                // Allocate the flagship. Decision Tree #1 (self), #2 (all to Núria), #3 (bad sequence).
                switch (d.staffing) {
                    case `advisory`:
                        // Deliberate power-sharing: star leads, Núria advises. The calibrated answer.
                        trustDelta += 12; riskDelta -= 14; influenceDelta += 8; ds.nuriaSecured = true; coachKey = `coach_r2_advisory`; break;
                    case `nuria`:
                        // Protects the account but signals you can't lead without her (Tree #2).
                        trustDelta += 6; riskDelta -= 16; influenceDelta -= 12; coachKey = `coach_r2_nuria`; break;
                    case `self`:
                        // Asserting authority on the most visible mandate = the overconfidence move (Tree #1).
                        trustDelta -= 16; riskDelta += 22; influenceDelta += 4; coachKey = `coach_r2_self`; break;
                    case `outsider`:
                        // Sidelines both Núria and the star; reads as distrust of your own bench.
                        trustDelta -= 6; riskDelta += 10; influenceDelta -= 2; coachKey = `coach_r2_outsider`; break;
                }

                // Sequencing drives trust INDEPENDENTLY of the decision (Decision Tree #3).
                if (d.sequence === `private`) {
                    trustDelta += 10; riskDelta -= 6;
                } else if (d.sequence === `public`) {
                    // Núria learns of her account being reassigned from the dashboard. Procedural injustice.
                    trustDelta -= 14; riskDelta += 16; ds.hrComplaints += 3; coachKey = `coach_r2_seqpublic`;
                } else if (d.sequence === `hr`) {
                    trustDelta -= 6; riskDelta += 4; coachKey = (coachKey === `coach_r2_advisory`) ? `coach_r2_seqhr` : coachKey;
                }

                // Credit attribution = replenishing or spending trust.
                if (d.credit === `nuria`) { trustDelta += 6; riskDelta -= 4; }
                else if (d.credit === `self`) { trustDelta -= 10; riskDelta += 6; influenceDelta -= 2; coachKey = `coach_r2_creditself`; }
                else if (d.credit === `team`) { trustDelta += 1; }

                summaryKey = (d.staffing === `advisory` && d.sequence === `private`) ? `sum_r2_good` : `sum_r2_weak`;
            } else if (round === 3) {
                // Calibrate the public forecast. Overconfidence gap = committed - calibrated EV.
                ds.committedForecast = d.forecast;
                ds.overconfGap = Math.round((d.forecast - this.CALIBRATED_EV) * 10) / 10;

                // A band protects you; a flat number turns an estimate into a promise (Tree #4).
                let promiseMode = (d.band === `flat`);
                if (d.band === `band`) {
                    influenceDelta += 6; trustDelta += 5; coachKey = `coach_r3_band`;
                } else if (d.band === `flat`) {
                    coachKey = `coach_r3_flat`;
                } else if (d.band === `hedge`) {
                    // No real number = sandbagging; protects you but signals weak leadership.
                    influenceDelta -= 8; trustDelta -= 2; coachKey = `coach_r3_hedge`;
                }

                // The miss: realized Q3 is €4.8M. Overcommitting above EV and missing burns credibility (Tree #1).
                ds.forecastMissed = d.forecast > this.REALIZED_Q3 + 0.05;
                const overshoot = Math.max(0, d.forecast - this.REALIZED_Q3); // €M missed
                if (ds.forecastMissed) {
                    // A missed flat promise costs far more than a missed, caveated estimate.
                    const missPenalty = overshoot * (promiseMode ? 26 : 12);
                    trustDelta -= Math.round(missPenalty);
                    influenceDelta -= Math.round(overshoot * (promiseMode ? 18 : 8));
                    if (d.forecast >= this.BAND_HIGH - 0.05) {
                        // Top-of-band bravado on day three (Tree #1): partners impressed, then exposed.
                        coachKey = `coach_r3_topband`;
                    } else if (promiseMode) {
                        coachKey = `coach_r3_flatmiss`;
                    }
                } else {
                    // Calibrated near or below EV that reality meets = credibility preserved.
                    if (d.forecast <= this.CALIBRATED_EV + 0.05 && d.forecast >= this.REALIZED_Q3 - 0.4) {
                        trustDelta += 6; influenceDelta += 5;
                    } else if (d.forecast < this.REALIZED_Q3 - 0.5) {
                        // Heavy sandbagging: you beat it, but you signalled timidity to partners.
                        influenceDelta -= 6; coachKey = `coach_r3_sandbag`;
                    }
                }

                // Consulting the team before committing = sharing, replenishes trust; owning it alone spends it.
                if (d.consult === `consult`) { trustDelta += 8; riskDelta -= 6; }
                else if (d.consult === `alone`) {
                    trustDelta -= 8; riskDelta += 6;
                    coachKey = (Math.abs(ds.overconfGap) < 0.2 && d.band === `band`) ? coachKey : `coach_r3_alone`;
                }

                summaryKey = (!ds.forecastMissed && d.band === `band` && d.consult === `consult`) ? `sum_r3_good` : `sum_r3_weak`;
            } else if (round === 4) {
                // Recover trust and retain Núria. Power-sharing vs capitulation is the core judgement.
                // Account risk drives whether Núria walks (Decision Tree #6: she holds €9.5M).
                switch (d.offer) {
                    case `redefine`:
                        trustDelta += 12; riskDelta -= 22; ds.nuriaRetained = true; coachKey = `coach_r4_redefine`; break;
                    case `raise`:
                        // Money without role/respect rarely retains a passed-over senior leader.
                        trustDelta += 2; riskDelta -= 6; coachKey = `coach_r4_raise`; break;
                    case `title`:
                        trustDelta -= 2; riskDelta += 2; coachKey = `coach_r4_title`; break;
                    case `nothing`:
                        // Ignoring exit risk (Tree #6 / Common Error 5): she walks, €9.5M and the forecast walk too.
                        trustDelta -= 12; riskDelta += 24; coachKey = `coach_r4_nothing`; break;
                }

                // Visible power-sharing BUILDS influence; refusing to share reads as fear.
                if (d.share === `cochair`) { influenceDelta += 12; trustDelta += 8; }
                else if (d.share === `credit`) { influenceDelta += 8; trustDelta += 10; riskDelta -= 6; }
                else if (d.share === `none`) { influenceDelta -= 8; trustDelta -= 6; coachKey = `coach_r4_noshare`; }

                // The boundary is what separates power-sharing from capitulation (Tree #2).
                if (d.boundary === `forecast`) {
                    influenceDelta += 10;
                } else if (d.boundary === `all`) {
                    // Giving veto = capitulation. Trust ticks, but influence collapses (Tree #2).
                    influenceDelta -= 20; trustDelta += 4; coachKey = `coach_r4_capitulate`;
                } else if (d.boundary === `none`) {
                    influenceDelta -= 14; coachKey = (coachKey === `coach_r4_redefine`) ? `coach_r4_nobound` : coachKey;
                }

                // Deliberate management of the trust budget under pressure.
                trustDelta += Math.round((d.recover - 60) / 8);
                influenceDelta += Math.round((d.recover - 60) / 10);

                summaryKey = (ds.nuriaRetained && d.boundary === `forecast` && (d.share === `cochair` || d.share === `credit`)) ? `sum_r4_good` : `sum_r4_weak`;
            }

            // Apply deltas with clamps.
            ds.trust = Math.max(0, Math.min(100, ds.trust + trustDelta));
            ds.accountRisk = Math.max(0, Math.min(100, ds.accountRisk + riskDelta));
            ds.influence = Math.max(0, Math.min(100, ds.influence + influenceDelta));

            // High account risk persisting past round 4 means Núria effectively exits.
            if (round === 4 && ds.accountRisk >= 60) ds.nuriaRetained = false;

            ds.trustHistory.push(ds.trust);
            ds.riskHistory.push(ds.accountRisk);

            const coachMsg = window.mySimulation.t(coachKey);
            ds.lastCoach = coachMsg;
            ds.coachMessages.push(coachMsg);
            const coachEl = document.getElementById(`coachText`);
            if (coachEl) coachEl.innerHTML = coachMsg;

            const self = this;
            setTimeout(function() {
                self._updateBriefing({ currentPeriod: state.currentPeriod + 1 });
            }, 500);

            // v1.1.0 FIX A — expose the composite (clamped 0-100) on the reporting paths.
            var _cal = Math.max(0, Math.round(100 - Math.abs(ds.overconfGap) * 60 - (ds.forecastMissed ? 25 : 0)));
            var _c = Math.max(0, Math.min(100, Math.round(ds.trust * 0.35 + (100 - ds.accountRisk) * 0.25 + ds.influence * 0.25 + _cal * 0.15)));
            ds.score = _c;
            ds.performance = { overallScore: _c };
            return {
                period: state.currentPeriod,
                score: _c,
                overallScore: _c,
                trust: ds.trust,
                trustDelta: trustDelta,
                accountRisk: ds.accountRisk,
                riskDelta: riskDelta,
                influence: ds.influence,
                influenceDelta: influenceDelta,
                overconfGap: ds.overconfGap,
                committedForecast: ds.committedForecast,
                forecastMissed: ds.forecastMissed,
                summary: window.mySimulation.t(summaryKey),
                coach: coachMsg
            };
        }

