        formatCompletionMessage(summary) {
            var t = (window.mySimulation && typeof window.mySimulation.t === 'function')
                ? window.mySimulation.t.bind(window.mySimulation)
                : function (k) { return k; };
            summary = summary || {};
            var score = (summary.score != null) ? summary.score : 0;
            var grade = summary.gradeKey ? t(summary.gradeKey) : '';
            var insights = summary.insights || [];
            var items = insights.map(function (s) { return '<li>' + s + '</li>'; }).join('');
            var metric = function (label, val) {
                return '<div class="ps-completion-metric"><span>' + label + '</span><strong>' + val + '</strong></div>';
            };
            var metrics = ''
                + metric(t('comp_trust_label'), (summary.trust != null ? summary.trust : '-'))
                + metric(t('comp_risk_label'), (summary.accountRisk != null ? summary.accountRisk : '-'))
                + metric(t('comp_infl_label'), (summary.influence != null ? summary.influence : '-'))
                + metric(t('comp_calib_label'), (summary.calibration != null ? summary.calibration : '-'));
            return ''
                + '<div class="ps-completion">'
                +   '<div class="ps-completion-heading">' + t('comp_heading') + '</div>'
                +   '<div class="ps-completion-verdict">' + grade + '</div>'
                +   '<div class="ps-completion-score">' + t('comp_score_label') + ': <strong>' + score + '</strong> / 100</div>'
                +   '<div class="ps-completion-metrics">' + metrics + '</div>'
                +   (items ? '<ul class="ps-completion-insights">' + items + '</ul>' : '')
                + '</div>';
        }

        getPerformanceSummary(history) {
            if (!history.length) return {};
            const ds = window.mySimulation.state.domainState;
            const trust = ds.trust, risk = ds.accountRisk, influence = ds.influence;
            const gapAbs = Math.abs(ds.overconfGap);

            // Calibration score: full marks for a tight, met forecast; penalised by the gap.
            const calibration = Math.max(0, Math.round(100 - gapAbs * 60 - (ds.forecastMissed ? 25 : 0)));
            // Composite leadership outcome.
            const composite = Math.round(trust * 0.35 + (100 - risk) * 0.25 + influence * 0.25 + calibration * 0.15);

            let performance = `Power Grab`;
            if (ds.nuriaRetained && trust >= 62 && influence >= 60 && composite >= 70) performance = `Calibrated Leader`;
            else if (ds.nuriaRetained && composite >= 58) performance = `Stabilised`;
            else if (composite >= 44) performance = `Fragile`;

            const insights = [];
            if (ds.nuriaRetained && influence >= 60) insights.push(window.mySimulation.t(`insight_durable`));
            else if (ds.nuriaRetained) insights.push(window.mySimulation.t(`insight_capitulation`));
            else insights.push(window.mySimulation.t(`insight_exit`));

            if (ds.forecastMissed) insights.push(window.mySimulation.t(`insight_overconf`));
            else if (ds.committedForecast > 0 && gapAbs <= 0.2) insights.push(window.mySimulation.t(`insight_calibrated`));
            if (trust < 45) insights.push(window.mySimulation.t(`insight_lowtrust`));
            if (influence < 45) insights.push(window.mySimulation.t(`insight_lowinfluence`));
            if (ds.hrComplaints >= 8) insights.push(window.mySimulation.t(`insight_hr`));

            const _sc = Math.max(0, Math.min(100, composite));
            const _gk = (ds.nuriaRetained && trust >= 62 && influence >= 60 && composite >= 70) ? 'grade_calibrated' : (ds.nuriaRetained && composite >= 58) ? 'grade_stabilised' : (composite >= 44) ? 'grade_fragile' : 'grade_grab';
            if (window.mySimulation && window.mySimulation.state && window.mySimulation.state.domainState) {
                window.mySimulation.state.domainState.score = _sc;
                window.mySimulation.state.domainState.performance = { overallScore: _sc, grade: window.mySimulation.t(_gk) };
            }
            return {
                score: _sc,
                gradeKey: _gk,
                trust: trust,
                accountRisk: risk,
                influence: influence,
                overconfGap: ds.overconfGap,
                calibration: calibration,
                composite: composite,
                performance: performance,
                nuriaRetained: ds.nuriaRetained,
                insights: insights
            };
        }

        getHint(state, results) {
            if (!results) return null;
            const ds = state.domainState;
            if (results.trustDelta <= -10) return window.mySimulation.t(`hint_trust_drop`);
            if (ds.accountRisk >= 60) return window.mySimulation.t(`hint_exit`);
            if (results.forecastMissed) return window.mySimulation.t(`hint_overconf`);
            if (ds.influence < 45) return window.mySimulation.t(`hint_capitulation`);
            if (ds.trust >= 72 && ds.accountRisk <= 25) return window.mySimulation.t(`hint_strong`);
            return null;
        }

